def solve(data):
    events = data.get('events', [])
    cutoff = data.get('cutoff', 10**9)
    rounding = data.get('rounding', 'half_up')

    # Filter before resolving duplicates, retaining original positions for tie breaks.
    winners = {}
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue
        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)
        rank = (event.get('revision', 0), position)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)

    balances = dict(data.get('opening', {}))
    for _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}
